1	//! Manifest reading and MatrixReport assembly for `callisto matrix`.
2	//! Private helpers only -- the public entry point is
3	//! `crate::commands::matrix::matrix`.
4	
5	/// Per-triple CI scheduling attributes for the 18 triples
6	/// `crate::napi::triple_to_role` recognises today. This table is NEW code:
7	/// `triple_to_role`'s `ManifestRole::Platform` carries only platform/arch/abi
8	/// and has no concept of hostRunner/useCross, so this cannot be derived from
9	/// it. Returns `None` for any triple `triple_to_role` does not recognise --
10	/// callers must treat that as the unrecognised-triple diagnostic path, never a silent
11	/// default.
12	pub(crate) fn triple_host_runner_use_cross(triple: &str) -> Option<(&'static str, bool)> {
13	    Some(match triple {
14	        "aarch64-apple-darwin" => ("macos-latest", false),
15	        "x86_64-apple-darwin" => ("macos-latest", false),
16	        "x86_64-unknown-linux-gnu" => ("ubuntu-latest", false),
17	        "x86_64-unknown-linux-musl" => ("ubuntu-latest", true),
18	        "aarch64-unknown-linux-gnu" => ("ubuntu-latest", true),
19	        "aarch64-unknown-linux-musl" => ("ubuntu-latest", true),
20	        "x86_64-pc-windows-msvc" => ("windows-latest", false),
21	        "i686-pc-windows-msvc" => ("windows-latest", false),
22	        "aarch64-pc-windows-msvc" => ("windows-latest", false),
23	        "armv7-unknown-linux-gnueabihf" => ("ubuntu-latest", true),
24	        "x86_64-unknown-freebsd" => ("ubuntu-latest", true),
25	        "aarch64-linux-android" => ("ubuntu-latest", true),
26	        "armv7-linux-androideabi" => ("ubuntu-latest", true),
27	        "riscv64gc-unknown-linux-gnu" => ("ubuntu-latest", true),
28	        "powerpc64le-unknown-linux-gnu" => ("ubuntu-latest", true),
29	        "s390x-unknown-linux-gnu" => ("ubuntu-latest", true),
30	        "wasm32-wasip1" => ("ubuntu-latest", false),
31	        "wasm32-unknown-unknown" => ("ubuntu-latest", false),
32	        _ => return None,
33	    })
34	}
35	
36	/// ArtifactName embeds the package's own (already workspace-unique)
37	/// name alongside platform/arch/abi, mirroring napi-rs's own
38	/// published-package and recommended-CI-artifact convention
39	/// (`<name>-<platform>-<arch>[-<abi>]`, e.g. `addon-darwin-arm64`,
40	/// `addon-linux-x64-gnu`) rather than the raw Rust target triple -- so two
41	/// packages sharing a triple never collide once fed through
42	/// `unique_by(.artifactName)` in `.github/actions/callisto-action/action.yml`.
43	/// `package_name` is sanitized first: `/` is one of
44	/// `actions/upload-artifact`'s forbidden artifact-name characters, and an
45	/// npm scoped package name (e.g. `@scope/addon`) carries one -- napi-rs's
46	/// own published *npm registry* package name may legitimately contain `/`
47	/// (e.g. `@scope/addon-darwin-arm64`), but this CI-internal artifact name
48	/// is a different namespace with its own, stricter constraint.
49	pub(crate) fn artifact_name_for_package_platform(
50	    package_name: &str,
51	    platform: &str,
52	    arch: &str,
53	    abi: Option<&str>,
54	) -> String {
55	    let package_name = package_name.replace('/', "-");
56	    match abi {
57	        Some(abi) => format!("{package_name}-{platform}-{arch}-{abi}"),
58	        None => format!("{package_name}-{platform}-{arch}"),
59	    }
60	}
61	
62	use std::path::Path;
63	
64	use callisto_model::{ManifestError, ManifestFormat, ManifestRole, PlatformTarget};
65	
66	use crate::error::GraphError;
67	use crate::napi::triple_to_role;
68	
69	/// Result of reading the `napi.targets` field from a package.json. Distinct
70	/// from `Option<Vec<String>>` so present-but-empty vs absent is a
71	/// type-level distinction, not a magic-empty-vec convention.
72	#[derive(Clone, Debug, PartialEq, Eq)]
73	pub(crate) enum NapiTargetsField {
74	    Absent,
75	    Present(Vec<String>),
76	}
77	
78	/// Reads and parses `pkg_json_path` as JSON, if it exists. `Ok(None)` when
79	/// the file is absent -- not every package has a `package.json`.
80	///
81	/// Callers needing more than one field out of the same `package.json` (e.g.
82	/// both `napi.targets` and `engines.node`, see `build_matrix_report`) must
83	/// call this once and pass the resulting `Value` to each field-extraction
84	/// function (`read_napi_targets`, `read_engines_node`) rather than letting
85	/// each one independently re-read and re-parse the file from disk.
86	pub(crate) fn parse_package_json(pkg_json_path: &Path) -> Result<Option<serde_json::Value>, GraphError> {
87	    let Some(content) = callisto_model::strict_fs::read_optional(pkg_json_path).map_err(|e| {
88	        GraphError::Manifest(ManifestError::Read {
89	            path: pkg_json_path.to_path_buf(),
90	            message: e.to_string(),
91	        })
92	    })?
93	    else {
94	        return Ok(None);
95	    };
96	    let val: serde_json::Value = serde_json::from_str(&content).map_err(|e| {
97	        GraphError::Manifest(ManifestError::Parse {
98	            path: pkg_json_path.to_path_buf(),
99	            format: ManifestFormat::PackageJson,
100	            message: e.to_string(),
101	        })
102	    })?;
103	    Ok(Some(val))
104	}
105	
106	/// Extracts `napi.targets` from an already-parsed `package.json` value (see
107	/// `parse_package_json`). A missing `napi` key or missing `napi.targets` key
108	/// is `Absent` (no platformTargets entry). A present `napi.targets`
109	/// that is not a JSON array of strings is a hard error -- strict
110	/// policy, propagating `callisto_manifests::read_napi_targets`'s error
111	/// as-is; unlike `NapiTargetsIndex::load`, which `.ok()`s the same shared
112	/// reader to silently drop non-array values instead.
113	pub(crate) fn read_napi_targets(pkg_json_path: &Path, val: &serde_json::Value) -> Result<NapiTargetsField, GraphError> {
114	    match callisto_manifests::read_napi_targets(pkg_json_path, val).map_err(GraphError::Manifest)? {
115	        Some(triples) => Ok(NapiTargetsField::Present(triples)),
116	        None => Ok(NapiTargetsField::Absent),
117	    }
118	}
119	
120	/// Builds a PlatformTarget for `triple`, combining `triple_to_role`'s
121	/// platform/arch/abi with this module's hostRunner/useCross/artifactName
122	/// table. Returns `None` when `triple` is not recognised by either --
123	/// callers must route that case to an UnrecognisedPlatformTriple diagnostic
124	/// rather than treating it as an error.
125	pub(crate) fn build_platform_target(triple: &str, package_dir: &str, package_name: &str) -> Option<PlatformTarget> {
126	    let ManifestRole::Platform { platform, arch, abi } = triple_to_role(triple)? else {
127	        return None;
128	    };
129	    let (host_runner, use_cross) = triple_host_runner_use_cross(triple)?;
130	    let artifact_name = artifact_name_for_package_platform(package_name, &platform, &arch, abi.as_deref());
131	    Some(PlatformTarget {
132	        triple: triple.to_string(),
133	        platform,
134	        arch,
135	        abi,
136	        host_runner: host_runner.to_string(),
