455	/// Assembles the full MatrixReport for `packages`. Map keys are each package's `ecosystem/name` id (the BTreeMap
456	/// ordering comes from this for free) so a Cargo package and an npm package sharing a name (the common napi split
457	/// layout) never collide on the same map entry; a package contributes no platformTargets entry when it declares neither
458	/// napi.targets nor [tool.maturin].targets, and no runtimeVersions entry when
459	/// it declares neither engines.node nor requires-python.
460	///
461	/// Each package's `package.json`/`pyproject.toml` is read and parsed at most
462	/// once here and the resulting value shared between the platform-target and
463	/// runtime-version extraction paths, instead of each independently
464	/// re-reading and re-parsing the same file from disk.
465	pub(crate) fn build_matrix_report(
466	    packages: &[MatrixPackageInput],
467	    napi_crates: Option<&[NapiCrate]>,
468	) -> Result<MatrixReport, GraphError> {
469	    let mut platform_targets = BTreeMap::new();
470	    let mut runtime_versions = BTreeMap::new();
471	    let mut diagnostics = Vec::new();
472	
473	    for pkg in packages {
474	        let pkg_json_val = parse_package_json(&pkg.dir_abs.join("package.json"))?;
475	        let pyproject_val = parse_pyproject_toml(&pkg.dir_abs.join("pyproject.toml"))?;
476	
477	        let (group, diags) = assemble_platform_target_group(
478	            &pkg.dir_abs,
479	            &pkg.dir_rel,
480	            &pkg.name,
481	            &pkg.id,
482	            pkg_json_val.as_ref(),
483	            pyproject_val.as_ref(),
484	        )?;
485	        if let Some(mut group) = group {
486	            if let (PlatformTargetKind::Napi, Some(pkg_json), Some(napi_crates), false) =
487	                (group.kind, pkg_json_val.as_ref(), napi_crates, group.targets.is_empty())
488	            {
489	                let manifest_path = napi_manifest_path(pkg, pkg_json, napi_crates)?;
490	                for target in &mut group.targets {
491	                    target.manifest_path = manifest_path.clone();
492	                }
493	            }
494	            platform_targets.insert(pkg.id.display_name(), group);
495	        }
496	        diagnostics.extend(diags);
497	
498	        let rv = assemble_runtime_versions(&pkg.dir_abs, pkg_json_val.as_ref(), pyproject_val.as_ref())?;
499	        if !rv.is_empty() {
500	            runtime_versions.insert(pkg.id.display_name(), rv);
501	        }
502	    }
503	
504	    Ok(MatrixReport {
505	        schema_version: callisto_model::PACKAGE_REPORT_SCHEMA_VERSION,
506	        platform_targets,
507	        runtime_versions,
508	        diagnostics,
509	    })
510	}
