297	use callisto_model::{Diagnostic, DiagnosticCode, DiagnosticSeverity, PlatformTargetGroup};
298	
299	/// Calls `select_platform_target_source` and, when a source is present,
300	/// builds a PlatformTarget for every declared triple,
301	/// excluding any triple `build_platform_target` does not recognise and
302	/// pushing an `UnrecognisedPlatformTriple` warning Diagnostic for each one
303	/// instead. `group.targets` is sorted ascending by triple string
304	/// before returning.
305	pub(crate) fn assemble_platform_target_group(
306	    package_dir_abs: &Path,
307	    package_dir_rel: &str,
308	    package_name: &str,
309	    package_id: &PackageId,
310	    pkg_json_val: Option<&serde_json::Value>,
311	    pyproject_val: Option<&toml::Value>,
312	) -> Result<(Option<PlatformTargetGroup>, Vec<Diagnostic>), GraphError> {
313	    let Some((kind, source, triples)) =
314	        select_platform_target_source(package_dir_abs, package_id, pkg_json_val, pyproject_val)?
315	    else {
316	        return Ok((None, Vec::new()));
317	    };
318	
319	    let mut targets = Vec::new();
320	    let mut diagnostics = Vec::new();
321	    let mut seen_triples = std::collections::BTreeSet::new();
322	    for triple in &triples {
323	        if !seen_triples.insert(triple.as_str()) {
324	            diagnostics.push(Diagnostic {
325	                code: DiagnosticCode::DuplicatePlatformTriple,
326	                severity: DiagnosticSeverity::Warning,
327	                message: format!(
328	                    "package `{package_name}` declares duplicate platform triple `{triple}` in `{source}`; only the first occurrence is used"
329	                ),
330	                package: Some(package_id.clone()),
331	                path: None,
332	                escalated_by: None,
333	                governed_by: None,
334	            });
335	            continue;
336	        }
337	        match build_platform_target(triple, package_dir_rel, package_name) {
338	            Some(t) => targets.push(t),
339	            None => diagnostics.push(Diagnostic {
340	                code: DiagnosticCode::UnrecognisedPlatformTriple,
341	                severity: DiagnosticSeverity::Warning,
342	                message: format!(
343	                    "package `{package_name}` declares unrecognised platform triple `{triple}` in `{source}`"
344	                ),
345	                package: Some(package_id.clone()),
346	                path: None,
347	                escalated_by: None,
348	                governed_by: None,
349	            }),
350	        }
351	    }
352	    targets.sort_by(|a, b| a.triple.cmp(&b.triple));
353	
354	    Ok((Some(PlatformTargetGroup { kind, source, targets }), diagnostics))
355	}
