512	/// One configured `[[release.artifact]]` cargo binary, resolved to its package.
513	pub(crate) struct ReleaseArtifactInput {
514	    pub id: PackageId,
515	    pub name: String,
516	    /// Workspace-root-relative package directory.
517	    pub dir_rel: String,
518	    pub target: String,
519	    pub asset_name: String,
520	}
521	
522	/// Adds one `cargo` group per package from its `[[release.artifact]]` entries;
523	/// each target's `artifactName` is the slot's configured asset name.
524	pub(crate) fn add_release_artifact_groups(
525	    report: &mut MatrixReport,
526	    artifacts: &[ReleaseArtifactInput],
527	) -> Result<(), GraphError> {
528	    const SOURCE: &str = "[[release.artifact]]";
529	    for artifact in artifacts {
530	        let group = report
531	            .platform_targets
532	            .entry(artifact.id.display_name())
533	            .or_insert_with(|| PlatformTargetGroup {
534	                kind: PlatformTargetKind::Cargo,
535	                source: SOURCE.to_owned(),
536	                targets: Vec::new(),
537	            });
538	        if group.kind != PlatformTargetKind::Cargo {
539	            return Err(GraphError::PlatformTargetsWithReleaseArtifacts {
540	                package: artifact.id.clone(),
541	                source_field: group.source.clone(),
542	            });
543	        }
544	        match build_platform_target(&artifact.target, &artifact.dir_rel, &artifact.name) {
545	            Some(mut target) => {
546	                target.artifact_name = artifact.asset_name.clone();
547	                group.targets.push(target);
548	            }
549	            None => report.diagnostics.push(Diagnostic {
550	                code: DiagnosticCode::UnrecognisedPlatformTriple,
551	                severity: DiagnosticSeverity::Warning,
552	                message: format!(
553	                    "package `{}` declares unrecognised platform triple `{}` in `{SOURCE}`",
554	                    artifact.name, artifact.target
555	                ),
556	                package: Some(artifact.id.clone()),
557	                path: None,
558	                escalated_by: None,
559	                governed_by: None,
560	            }),
561	        }
562	        group.targets.sort_by(|a, b| {
563	            a.triple
564	                .cmp(&b.triple)
565	                .then_with(|| a.artifact_name.cmp(&b.artifact_name))
566	        });
567	    }
568	    report
569	        .platform_targets
570	        .retain(|_, group| !group.targets.is_empty() || group.kind != PlatformTargetKind::Cargo);
571	    Ok(())
572	}
