1	use std::collections::BTreeMap;
2	use std::fmt;
3	
4	use schemars::JsonSchema;
5	use serde::{Deserialize, Serialize};
6	
7	use crate::{Diagnostic, Report};
8	
9	/// Top-level report output from `callisto matrix --format json`.
10	///
11	/// `platform_targets`/`runtime_versions` are keyed by each package's `ecosystem/name` identity, so a Cargo crate and
12	/// an npm package sharing a name never collide on one entry. BTreeMap guarantees lexicographic key ordering by that
13	/// id without a separate sort step.
14	#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize, JsonSchema)]
15	#[serde(rename_all = "camelCase")]
16	pub struct MatrixReport {
17	    pub schema_version: u32,
18	    pub platform_targets: BTreeMap<String, PlatformTargetGroup>,
19	    pub runtime_versions: BTreeMap<String, Vec<RuntimeVersionEntry>>,
20	
21	    #[serde(default, skip_serializing_if = "Vec::is_empty")]
22	    pub diagnostics: Vec<Diagnostic>,
23	}
24	
25	impl Report for MatrixReport {
26	    const COMMAND: &'static str = "matrix";
27	
28	    fn schema_version(&self) -> u32 {
29	        self.schema_version
30	    }
31	
32	    fn diagnostics(&self) -> &[Diagnostic] {
33	        &self.diagnostics
34	    }
35	}
36	
37	/// One package's build target group: napi, maturin, or cargo `[[release.artifact]]`
38	/// binaries -- never more than one (see GraphError::ConflictingPlatformTargetSources).
39	#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize, JsonSchema)]
40	#[serde(rename_all = "camelCase")]
41	pub struct PlatformTargetGroup {
42	    pub kind: PlatformTargetKind,
43	    /// Raw manifest field name ("napi.targets", "[tool.maturin].targets", or
44	    /// "[[release.artifact]]"),
45	    /// used for audit output only -- not a filesystem path.
46	    pub source: String,
47	    /// Sorted ascending by triple string before serialization.
48	    pub targets: Vec<PlatformTarget>,
49	}
50	
51	/// Deliberately omits a DotnetAot variant; out of scope for this spec.
52	#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize, Deserialize, JsonSchema)]
53	#[serde(rename_all = "lowercase")]
54	pub enum PlatformTargetKind {
55	    Napi,
56	    Maturin,
57	    /// A cargo binary configured as a `[[release.artifact]]`.
58	    Cargo,
59	}
60	
61	impl fmt::Display for PlatformTargetKind {
62	    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
63	        f.write_str(match self {
64	            PlatformTargetKind::Napi => "napi",
65	            PlatformTargetKind::Maturin => "maturin",
