}

/// PlatformTargets/runtimeVersions keys and each group's targets[]
/// are lexicographically ordered across 3+ packages. An explicitly
/// empty napi.targets = [] still produces a present platformTargets entry.
#[test]
fn matrix_orders_keys_lexicographically_across_three_packages() {
    use std::process::Command;

    let tmp = tempfile::TempDir::new().unwrap();
    callisto_fixtures::git::init_repo(tmp.path());
    let root = tmp.path();
    std::fs::write(root.join("Cargo.toml"), "[workspace]\nmembers = []\nresolver = \"2\"\n").unwrap();
    std::fs::write(root.join("callisto.toml"), "").unwrap();

    let zeta = root.join("zeta");
    std::fs::create_dir_all(&zeta).unwrap();
    std::fs::write(
        zeta.join("package.json"),
        r#"{"name":"zeta","napi":{"targets":["x86_64-unknown-linux-gnu","aarch64-apple-darwin"]}}"#,
    )
    .unwrap();

    let alpha = root.join("alpha");
    std::fs::create_dir_all(&alpha).unwrap();
    std::fs::write(alpha.join("package.json"), r#"{"name":"alpha","napi":{"targets":[]}}"#).unwrap();

    let mid = root.join("mid");
    std::fs::create_dir_all(&mid).unwrap();
    std::fs::write(
        mid.join("package.json"),
        r#"{"name":"mid","napi":{"targets":["aarch64-apple-darwin"]}}"#,
    )
    .unwrap();

    napi_crate(root, "zeta");
    napi_crate(root, "mid");
    let bin = env!("CARGO_BIN_EXE_callisto");
    let output = Command::new(bin)
        .args(["--cwd", &root.to_string_lossy(), "--format", "json", "matrix"])
        .output()
        .unwrap();
    assert!(
        output.status.success(),
        "stderr: {}",
        String::from_utf8_lossy(&output.stderr)
    );

    let json: serde_json::Value = serde_json::from_slice(&output.stdout).unwrap();
    let keys: Vec<&String> = json["platformTargets"].as_object().unwrap().keys().collect();
    assert_eq!(
        keys,
        vec!["cargo/mid", "cargo/zeta", "npm/alpha"],
        "keys must be lexicographically ordered"
    );

    // Alpha's entry is present-but-empty, not absent.
    assert_eq!(json["platformTargets"]["npm/alpha"]["targets"], serde_json::json!([]));

    // Within zeta's group, targets[] must be ascending by triple.
    let zeta_triples: Vec<String> = json["platformTargets"]["cargo/zeta"]["targets"]
        .as_array()
        .unwrap()
        .iter()
        .map(|t| t["triple"].as_str().unwrap().to_string())
        .collect();
    assert_eq!(
        zeta_triples,
        vec![
            "aarch64-apple-darwin".to_string(),
            "x86_64-unknown-linux-gnu".to_string()
        ]
    );
}

